/// Linguist's language type.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum LanguageKind {
    /// A programming language.
    Programming,
    /// A markup language (HTML, Markdown).
    Markup,
    /// A data format (JSON, YAML).
    Data,
    /// Prose (plain text formats).
    Prose,
}
